attributes:
sx={{
        width: "100%",
        minWidth: 0,
        maxWidth: searchMaxWidth ? { lg: searchMaxWidth } : undefined,
      }}

voiceContext={activeView === "main" && !agentWorkOpen ? {
            projectId: conversation.projectId,
            conversationId,
            agents: routingAgents,
            selectedAgentId: commandTargetAgent?.conversationId === conversationId ? commandTargetAgent.id : undefined,
          } : undefined}

defaultDestination={lastContinuationDestination ? {
            handle: lastContinuationDestination.agent.handle,
            binding: {
              projectId: conversation.projectId,
              handle: lastContinuationDestination.agent.handle,
              agentId: lastContinuationDestination.agent.id,
              currentHandle: lastContinuationDestination.agent.handle,
              currentTitle: lastContinuationDestination.agent.title,
            },
            selectionKey: lastContinuationDestination.selectionKey,
          } : undefined}

onCommand={
            commandTargetAgent
              ? (command, argumentsText) => {
                  const invocation = api.invokeProviderCommand(
                    commandTargetAgent.id,
                    {
                      name: command.name,
                      ...(argumentsText ? { argumentsText } : {}),
                    },
                  );
                  return invocation.then(result => {
                    if (result.outcome && result.outcome !== "completed") throw new Error(result.message ?? "Provider command completion is unconfirmed. Do not repeat the command.");
                    if (result.message) setQueuedMessageNotice(result.message);
                    else notify({ key: "provider-command", message: `/${command.name} Invoked` });
                  });
                }
              : undefined
          }

placeholder={
            engineReady
              ? "Write a message…"
              : "Choose an available Agent with # or use #broadcast"
          }

inputProps={{
            maxLength: 200,
            "aria-label": "Search Ponderosa",
            role: "combobox",
            "aria-expanded": open,
            "aria-controls": "global-search-results",
            "aria-activedescendant": activeIndex >= 0 ? `global-search-option-${activeIndex}` : undefined,
          }}

onChange={(event) => {
            const file = event.target.files?.[0];
            event.target.value = "";
            if (file) void loadFile(file);
          }}

onPasteCapture={(event) => {
          const field = event.target;
          if (!(field instanceof HTMLTextAreaElement)) return;
          const pasted = event.clipboardData?.getData("text/plain");
          if (!pasted) return;
          const before = field.value.slice(0, field.selectionStart);
          const after = field.value.slice(field.selectionEnd);
          const nextLength = before.length + pasted.length + after.length;
          if (nextLength < LARGE_PASTE_CHARACTERS) return;
          event.preventDefault();
          setJsonText("");
          const blob = new Blob([before, pasted, after], { type: "application/json" });
          inspectPackage(blob, "pasted-agent-package.json");
        }}

defaultDestination={activeReplyTarget ? {
            handle: activeReplyTarget.handle,
            binding: {
              projectId: activeReplyTarget.projectId,
              handle: activeReplyTarget.handle,
              agentId: activeReplyTarget.id,
              currentHandle: activeReplyTarget.handle,
              currentTitle: activeReplyTarget.title,
            },
            selectionKey: `agent:${activeReplyTarget.id}:${activeReplyTarget.title}`,
          } : undefined}

requiredRecipient={activeReplyTarget ? {
            handle: activeReplyTarget.handle,
            title: activeReplyTarget.title,
            onClear: () => clearReplyTarget(false),
          } : undefined}

recipientRequiredMessage={
            selected && !selected.directMessageAgent
              ? "This message does not identify an active Agent you can message."
              : "Mention an Agent or choose a message to reply to."
          }

voiceContext={activeReplyTarget && composerConversationId ? {
            projectId: activeReplyTarget.projectId,
            conversationId: composerConversationId,
            agents: projectAgentsQuery.data ?? [],
            selectedAgentId: activeReplyTarget.id,
            lockAgent: true,
          } : undefined}

attachmentsUnavailableReason={
            composerConversationId
              ? undefined
              : "Select a source Chat before adding attachments."
          }

placeholder={
            activeReplyTarget
              ? `Message ${activeReplyTarget.title} directly`
              : "Mention an Agent or choose a message to reply to"
          }

onChange={(event) => {
        const file = event.target.files?.[0];
        event.target.value = "";
        if (file) form.upload(file);
      }}

helperText={["broadcast", "everyone", "user"].includes(form.handle) ? "This handle is reserved. Choose another."
        : !/^[a-z][a-z0-9_-]{1,31}$/u.test(form.handle) ? "Use 2–32 characters, starting with a letter: lowercase letters, numbers, underscores, or hyphens."
        : handleHelperText}

helperText={valid
        ? "Applies immediately; active Runs finish normally."
        : `Enter a whole number from ${MIN_AGENT_RUN_CONCURRENCY} to ${MAX_AGENT_RUN_CONCURRENCY}.`}

helperText={
              rolloverFractionError ??
              "Requires a provider-reported context window size."
            }

helperText={
              idAlreadyExists
                ? "This model id is already available."
                : "Use the exact versioned id accepted by Claude Code."
            }

onKeyDown={event => {
        if (composing.current || event.nativeEvent.isComposing || event.key.length === 1) return;
        if (["Backspace", "Delete", "Enter", "Tab", "Escape", "ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
          event.preventDefault(); onKey(event.key); clear();
          if (event.key === "Escape") event.currentTarget.blur();
        }
      }}

onCompositionEnd={event => {
          composing.current = false;
          if (event.currentTarget.value) sendInput({ kind: "type", text: event.currentTarget.value });
          event.currentTarget.value = "";
        }}

onChange={event => {
          if (composing.current) return;
          if (event.target.value) sendInput({ kind: "type", text: event.target.value });
          event.target.value = "";
        }}

onKeyDown={event => {
          if (composing.current || event.nativeEvent.isComposing) return;
          if (event.key === "Escape") {
            event.stopPropagation();
            event.currentTarget.blur();
            event.currentTarget.closest('[role="dialog"]')?.querySelector<HTMLInputElement>('input[aria-label="Website address"]')?.focus();
            return;
          }
          // Native text entry/paste feeds onChange, preserving Unicode and IME.
          if (["Shift", "Control", "Alt", "Meta"].includes(event.key)) return;
          if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "v") return;
          if (event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) return;
          event.preventDefault();
          // Control is the browser API's primary-shortcut token; the host driver
          // maps it to Command when Chrome runs on macOS.
          const modifiers = `${event.ctrlKey || event.metaKey ? "Control+" : ""}${event.altKey ? "Alt+" : ""}${event.shiftKey ? "Shift+" : ""}`;
          sendInput({ kind: "key", key: modifiers + event.key });
        }}

onFocus={() => {
                // Native focus can restore a pre-chip DOM selection after the
                // focus handler. Reconcile once it has finished, before typing.
                queueMicrotask(() => bridgeRef.current?.placeCaretAfterLoneMention());
                requestAnimationFrame(() => bridgeRef.current?.placeCaretAfterLoneMention());
              }}

onKeyDown={(event) => {
              if (event.key === "Escape") setEditingId(undefined);
              if (event.key === "Enter" && !event.shiftKey && editingText.trim()) {
                event.preventDefault();
                run(() => onEdit(message, editingText.trim()), () => setEditingId(undefined));
              }
            }}

onPaste={event => {
              const files = filesFromClipboard(event.clipboardData.items, event.clipboardData.files);
              if (!files.length) return;
              event.preventDefault(); event.stopPropagation();
              if (canEdit.current && draft.canAttach) draft.addFiles(files, question?.id);
            }}

onChange={(event) => {
            setValues((current) => ({ ...current, [field.name]: event.target.value }));
            setFieldErrors((current) => {
              const { [field.name]: _removed, ...rest } = current;
              return rest;
            });
          }}
